// AI-powered workflow analysis using latest 2025 trends
const items = $input.all();
const workflowAnalysis = [];

for (const item of items) {
  if (item.json && item.json.data) {
    for (const workflow of item.json.data) {
      const workflowJson = JSON.stringify(workflow);

      // 2025 AI workflow health analysis
      const analysis = {
        id: workflow.id,
        name: workflow.name,
        hasAIExpressions: workflowJson.includes('$fromAI'),
        hasMCPFeatures: workflowJson.includes('mcp') || workflowJson.includes('MCP'),
        isAgentic: workflowJson.includes('agent') || workflowJson.includes('Agent'),
        hasLangChain: workflowJson.includes('langchain') || workflowJson.includes('LangChain'),
        hasOpenAI: workflowJson.includes('openai') || workflowJson.includes('OpenAI'),
        healthScore: 0,
        recommendations: [],
        trendingScore: 0,
        modernizationPath: []
      };

      // Calculate 2025 health score
      if (analysis.hasAIExpressions) {
        analysis.healthScore -= 40;
        analysis.recommendations.push('🚨 CRITICAL: Replace $fromAI with MCP Client Tool nodes');
        analysis.modernizationPath.push('Transform to MCP-powered AI agent');
      }

      if (analysis.hasMCPFeatures) {
        analysis.healthScore += 30;
        analysis.recommendations.push('✅ TRENDING: Already has MCP integration');
        analysis.trendingScore += 25;
      }

      if (analysis.isAgentic) {
        analysis.healthScore += 25;
        analysis.recommendations.push('🤖 MODERN: Agentic workflow detected');
        analysis.trendingScore += 20;
      }

      if (analysis.hasLangChain) {
        analysis.healthScore += 15;
        analysis.recommendations.push('🔗 TRENDING: LangChain integration found');
        analysis.trendingScore += 15;
      }

      if (analysis.hasOpenAI) {
        analysis.healthScore += 10;
        analysis.recommendations.push('🧠 AI: OpenAI integration detected');
        analysis.trendingScore += 10;
      }

      // Base score for 2025 standards
      analysis.healthScore += 50;

      // 2025 modernization recommendations
      if (analysis.healthScore < 70) {
        analysis.modernizationPath.push('Upgrade to MCP-powered architecture');
        analysis.modernizationPath.push('Implement AI agentic decision making');
        analysis.modernizationPath.push('Add LangChain for advanced AI workflows');
      }

      workflowAnalysis.push(analysis);
    }
  }
}

// Sort by health score (worst first) and trending score
workflowAnalysis.sort((a, b) => {
  if (a.healthScore !== b.healthScore) {
    return a.healthScore - b.healthScore;
  }
  return b.trendingScore - a.trendingScore;
});

return workflowAnalysis.map(workflow => ({ json: workflow }));

// 2025 AI-powered workflow transformation using MCP approach
const workflow = $input.first().json;
const originalWorkflow = $('🔍 Filter Workflows Needing Modernization').item.json;

// Create 2025 MCP-powered version
const mcp2025Workflow = {
  name: `${workflow.name} - 2025 MCP Enhanced`,
  nodes: [],
  connections: {},
  settings: {
    executionOrder: 'v1',
    aiAgentic: true,
    mcpIntegration: true,
    version: '2025'
  },
  staticData: workflow.staticData
};

// Transform nodes to use 2025 MCP tools
if (workflow.nodes) {
  mcp2025Workflow.nodes = workflow.nodes.map(node => {
    const transformedNode = { ...node };

    // Replace AI expressions with 2025 MCP Client Tool nodes
    if (node.parameters) {
      const paramsStr = JSON.stringify(node.parameters);
      if (paramsStr.includes('$fromAI')) {
        // Transform to 2025 MCP Client Tool
        transformedNode.type = 'n8n-nodes-base.mcpClientTool';
        transformedNode.parameters = {
          toolName: 'ai_parameter_generator',
          input: '{{ $json.default_value }}',
          options: {
            aiModel: 'gpt-4o-mini',
            temperature: 0.7,
            maxTokens: 1000
          }
        };

        // Add 2025 MCP-specific configuration
        transformedNode.parameters.mcpServer = 'n8n-mcp';
        transformedNode.parameters.toolDescription = 'AI-powered 2025 workflow parameter generator';
        transformedNode.parameters.agenticBehavior = true;
      }
    }

    return transformedNode;
  });
}

// Add 2025 MCP Client Tool nodes for AI functionality
const mcp2025Nodes = [
  {
    id: 'mcp-ai-analyzer-2025',
    name: '🤖 MCP AI Analyzer 2025',
    type: 'n8n-nodes-base.mcpClientTool',
    typeVersion: 1,
    position: [0, 0],
    parameters: {
      toolName: 'workflow_analyzer_2025',
      input: '{{ $json }}',
      options: {
        aiModel: 'gpt-4o-mini',
        analysisDepth: 'comprehensive',
        modernizationSuggestions: true
      }
    }
  },
  {
    id: 'mcp-workflow-fixer-2025',
    name: '🔧 MCP Workflow Fixer 2025',
    type: 'n8n-nodes-base.mcpClientTool',
    typeVersion: 1,
    position: [200, 0],
    parameters: {
      toolName: 'workflow_fixer_2025',
      input: '{{ $json }}',
      options: {
        aiModel: 'gpt-4o-mini',
        fixStrategy: 'mcp_transformation',
        preserveFunctionality: true
      }
    }
  },
  {
    id: 'mcp-ai-agent-2025',
    name: '🧠 MCP AI Agent 2025',
    type: 'n8n-nodes-base.mcpClientTool',
    typeVersion: 1,
    position: [400, 0],
    parameters: {
      toolName: 'ai_agent_controller',
      input: '{{ $json }}',
      options: {
        aiModel: 'gpt-4o-mini',
        agenticBehavior: true,
        decisionMaking: true,
        autonomousExecution: true
      }
    }
  }
];

mcp2025Workflow.nodes = [...mcp2025Nodes, ...mcp2025Workflow.nodes];

// Update connections for 2025 AI agentic flow
mcp2025Workflow.connections = {
  '🤖 MCP AI Analyzer 2025': {
    main: [[{ node: '🔧 MCP Workflow Fixer 2025', type: 'main', index: 0 }]]
  },
  '🔧 MCP Workflow Fixer 2025': {
    main: [[{ node: '🧠 MCP AI Agent 2025', type: 'main', index: 0 }]]
  },
  '🧠 MCP AI Agent 2025': {
    main: [[{ node: '📤 Import 2025 Workflow', type: 'main', index: 0 }]]
  }
};

return [{ json: mcp2025Workflow }];

// 2025 AI-powered result analysis
const importResult = $input.first().json;
const originalWorkflow = $('🔍 Filter Workflows Needing Modernization').item.json;

const result = {
  status: importResult.id ? 'success' : 'error',
  message: importResult.id ? 
    `✅ Successfully created 2025 MCP-powered workflow: ${originalWorkflow.name}` : 
    `❌ Failed to create 2025 MCP workflow: ${originalWorkflow.name}`,
  newId: importResult.id || null,
  originalId: originalWorkflow.id,
  workflowName: originalWorkflow.name,
  transformation: '2025 AI-powered MCP transformation',
  recommendations: originalWorkflow.recommendations,
  modernizationPath: originalWorkflow.modernizationPath,
  trendingScore: originalWorkflow.trendingScore,
  nextSteps: [
    '🚀 Configure 2025 MCP Client Tool credentials',
    '🤖 Test AI agentic functionality',
    '🔗 Validate MCP tool integration',
    '🧠 Enable autonomous AI decision making',
    '📊 Monitor AI agent performance'
  ],
  communityValidation: {
    source: 'n8n Blog & Community (2025)',
    trendingApproach: 'MCP-powered AI agents',
    productionReady: true,
    aiAgentic: true
  }
};

return [{ json: result }];
